const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='exit-nine:player:story:checkpoint:v14';
let volume=.45,lastFoot=0,toastUntil=0,modal=null,menu=true,last=performance.now(),quality=480,sensitivity=.0017,reticle=null,ambience=0;
const keys=new Set();
const soundscape=new Soundscape();
const music=new MusicDirector(soundscape);
const characterVoice=new CharacterVoice(soundscape,{getState:()=>game.s});
function sound(kind,options){soundscape.play(kind,options);}
function startAudio(){soundscape.start();characterVoice.load();}
function notice(text){const c=current(game.s);if(sceneInteraction.actorId&&c&&text.startsWith(c.cn+'：'))return;if((world?.device||sceneInteraction.actorId)&&text.startsWith('笔记已更新'))return;$('toast').textContent=text;$('toast').classList.add('visible');toastUntil=performance.now()+5500;}
const world=new World($('world'));world.presentationSound=sound;
const weather=new WinterWeather(world);world.winterWeather=weather;installCharacterCache(world);world.targets.push({id:'evacuate',pos:world.camera.position.clone().set(-13.15,1.2,-16.2),name:'确认 N9 · 上车离站'});
const game=new CampaignGame({notice,sound,dialogue:(text,options)=>characterVoice.speak(text,options),storyVoiceBusy:()=>!!(characterVoice.source||characterVoice.pending||characterVoice.waiting||characterVoice.queue.length),checkpoint:s=>{if(s.debugUsed)return;try{localStorage.setItem(SAVE,JSON.stringify(s));}catch{notice('浏览器未允许保存，当前游戏仍可继续。');}},nav:(a,b,s)=>world.path(a,b,s),canSee:(a,b,s)=>world.sees(a,b,s),canOccupy:(p,s)=>world.canMove(p.x,p.z,s,.25),canDrop:(p,s)=>flatCargoSpot(p,s)&&distance(p,s.player)>.68&&!s.actors.some(a=>a.mode!=='dead'&&distance(p,a)<.72)&&world.canMove(p.x,p.z,s,.36)&&!s.crates.some(c=>c.id!==s.carry?.id&&['floor','warehouse'].includes(c.place)&&distance(c,p)<.7)});
game.dialogueCaption=()=>characterVoice.caption||characterVoice.pending?.signature||characterVoice.resume?.request?.signature||characterVoice.waiting?.signature||'';
const sceneInteraction=new CampaignInteraction(game,world);
game.onFatal=()=>{sceneInteraction.close();keys.clear();characterVoice.stop('fatal');$('resume').hidden=true;};
game.onSequenceStart=()=>{sceneInteraction.close();keys.clear();$('resume').hidden=true;characterVoice.sync(game.s,{conversationId:null});};
let openingReturn=null,seamlessControl=false;
const opening=new OpeningSequence(world,soundscape,{clearInput:()=>keys.clear(),requestControl:captureOpeningPointer,finish:({preview})=>{keys.clear();if(preview&&openingReturn){game.s=openingReturn;openingReturn=null;seamlessControl=false;showMenu();world.sync(game.s,0);return;}game.save('末班车抵达 · 制服与交班完成');play({seamless:true});}});
function captureOpeningPointer(){startAudio();if(document.pointerLockElement===world.renderer.domElement)return;try{world.renderer.domElement.requestPointerLock?.()?.catch?.(()=>{});}catch{}}
function beginOpening(preview=false){characterVoice.stop('opening');sceneInteraction.close();keys.clear();toastUntil=0;$('toast').classList.remove('visible');if(preview){openingReturn=game.s;game.s=campaignState();}menu=false;modal=null;$('screen').hidden=true;$('modal').hidden=true;$('resume').hidden=true;document.body.classList.remove('menu');seamlessControl=true;opening.start(game.s,{preview});captureOpeningPointer();}
function beginFirstNight(withOpening=true){game.s=campaignState();ambience=0;lastFoot=0;if(withOpening)beginOpening();else play();}
const playerShell=new PlayerShell({onEnter:()=>{startAudio();sound('keyboard');}});
function saved(){try{return JSON.parse(localStorage.getItem(SAVE)||'null');}catch{return null;}}
function button(text,fn,kind=''){const b=document.createElement('button');b.textContent=text;b.className=kind;b.onclick=fn;return b;}
function pointerCaptureFailed(){if(menu||modal||sequenceActive(game.s)||sceneInteraction.active)return;if(game.s.paused){$('resume').hidden=false;return;}$('resume').hidden=true;notice('鼠标未锁定，点击画面重试；Esc 可暂停。');}
function lock({silent=false}={}){if(menu||modal)return;if(world.device==='register'){$('resume').hidden=true;return;}startAudio();if(document.pointerLockElement===world.renderer.domElement)return;try{const result=world.renderer.domElement.requestPointerLock?.();result?.catch?.(()=>{if(!silent&&!seamlessControl&&!menu&&!modal&&!sequenceActive(game.s)&&!sceneInteraction.active&&world.device!=='register')pointerCaptureFailed();});}catch{if(!silent&&!seamlessControl&&!menu&&!modal&&!sequenceActive(game.s)&&!sceneInteraction.active&&world.device!=='register')pointerCaptureFailed();}}
function play({seamless=false}={}){seamlessControl=seamless&&!document.pointerLockElement;toastUntil=0;$('toast').classList.remove('visible');sceneInteraction.close();menu=false;modal=null;document.body.classList.remove('menu');$('screen').hidden=true;$('modal').hidden=true;game.start();$('resume').hidden=true;keys.clear();lock({silent:seamless});}
function showMenu(){persistSession(game,{openingActive:opening.active});seamlessControl=false;sceneInteraction.close();keys.clear();menu=true;game.s.paused=true;document.exitPointerLock?.();$('screen').hidden=false;$('modal').hidden=true;$('resume').hidden=true;document.body.classList.add('menu');const actions=$('menu-actions');actions.replaceChildren();const ongoing=(game.s.time>0||game.s.openingSeen||game.s.night>1)&&!game.s.finished,checkpoint=saved();
 if(ongoing)actions.append(button('继续夜班',play,'primary'));
 else if(checkpoint)actions.append(button('继续存档 · 第 '+(checkpoint.night||1)+' 晚',()=>{if(game.load(checkpoint))play();else notice('这份存档无法读取，请重新开始。');},'primary'));
 else actions.append(button('开始游戏',()=>beginFirstNight(true),'primary'));
 if(ongoing||checkpoint)actions.append(button('重新开始',()=>playerShell.confirmNew(()=>beginFirstNight(true)),'subtle'));
 if(game.s.time>0)actions.append(button('本夜记录',()=>{menu=false;$('screen').hidden=true;openPanel('records');}));
 if(!world.characterWarmup?.ready){for(const b of actions.querySelectorAll('button'))b.disabled=true;actions.firstElementChild.textContent='正在准备场景…';}
 playerShell.home({ongoing,checkpoint,night:game.s.night,state:game.s,task:campaignTask(game.s)||task(game.s)});
}
function openPanel(kind){sceneInteraction.close();modal=kind;game.s.paused=true;keys.clear();document.exitPointerLock?.();$('resume').hidden=true;$('modal').hidden=false;renderPanel();}
function closePanel(){if(modal==='settlement'){modal=null;showMenu();return;}modal=null;$('modal').hidden=true;if(game.s.finished){showMenu();return;}game.s.paused=false;lock();if(sequenceActive(game.s)){seamlessControl=true;$('resume').hidden=true;}else if(!document.pointerLockElement&&!sceneInteraction.active&&!game.s.deathCinematic)$('resume').hidden=false;}
$('panel-close').onclick=closePanel;
function panel(title,kicker,body,actions=[]){$('panel-close').innerHTML=(modal==='settlement'?'返回菜单':'关闭')+' <kbd>Esc</kbd>';$('panel-close').setAttribute('aria-label',modal==='settlement'?'返回菜单':'关闭面板');$('panel-title').textContent=title;$('panel-kicker').textContent=({notes:'E9 / 员工留存',manual:'E9 / 员工手册',map:'E9 / 站点平面图',records:'E9 / 值班记录',settlement:'E9 / 交班结算'})[modal]||'E9 / 员工留存';$('panel-body').innerHTML=body;$('panel-actions').replaceChildren(...actions);}
function renderPanel(){const s=game.s,c=current(s);
 if(modal==='settlement'){renderSettlement();return;}
 if(modal==='manual'){s.manual=true;panel('夜班现场手册','EXIT NINE / FIELD NOTES',MANUAL.map(([a,b])=>`<h3>${esc(a)}</h3><p>${esc(b)}</p>`).join(''),[button('合上手册',closePanel,'primary')]);}
 if(modal==='map'){panel('站点平面图','SITE PLAN / NORTH ↑',`<div class="map">${siteMapSVG(s.player)}</div><p>员工室从扩大后的仓库进入。电闸在建筑右侧微光通道尽头。</p>`,[button('收起地图',closePanel,'primary')]);}
 if(modal==='notes'){panel('当班笔记','OBSERVATIONS / NO AUTOMATIC VERDICT',`<div class="current-assignment"><small>当班事项</small><strong>${esc((campaignTask(s)||task(s)).title)}</strong><p>${esc((campaignTask(s)||task(s)).detail)}</p></div>`+(Object.values(s.evidence).map(v=>`<p class="note">${esc(v)}</p>`).join('')||'<p>还没有记录。听来意、查看证件、查终端，以及近处实际看到的异常都会记在这里。</p>'),[button('继续工作',closePanel,'primary')]);}
 if(modal==='records'){panel(s.finished?s.outcome:'本夜工作记录','SHIFT REPORT',`<div class="end-record"><div><b>${stockCount(s)}/${s.crates.length}</b><span>货箱上架</span></div><div><b>${s.clean.length}/3</b><span>地面清洁</span></div><div><b>$${s.revenue.toFixed(2)}</b><span>销售额</span></div><div><b>${s.mistakes}</b><span>错误决定 / 拒绝真人</span></div></div><h3>最近事件</h3>${s.log.slice(0,10).map(v=>`<p class="note">${esc(v)}</p>`).join('')}<p class="compact">本次游玩 ${Math.floor(s.time/60)} 分 ${Math.floor(s.time%60)} 秒（不含暂停）。进度在暂停与离开时自动保存。</p>`,[button(s.finished?'返回菜单':'继续夜班',()=>{if(s.finished){modal=null;showMenu();}else closePanel();},'primary')]);}
}
function renderSettlement(){const s=game.s,last=s.history.at(-1);if(!last)return;const missing=Math.max(0,s.rentTarget-s.rentFund);const body=`<p class="quote">${esc(s.outcome==='提前离职 · 换个地方挣'?'亚历克斯决定不再接受后续班次，领取已确认收入，另找工作。':NIGHTS[s.night].closing)}</p><div class="end-record"><div><b>${money(last.sales)}</b><span>本晚营业额</span></div><div><b>${money(last.net)}</b><span>个人工资与提成 → 租房基金</span></div><div><b>${money(s.rentFund)} / ${money(s.rentTarget)}</b><span>租房基金 · 还差 ${money(missing)}</span></div><div><b>${money(s.wallet)}</b><span>店铺经营资金 · 仅用于补给</span></div></div><p>本晚记住的事：${esc(last.clue)}</p><p>${esc(s.outcome||last.ending)}</p>`;const actions=[];if(!s.campaignFinished){for(const p of BUYABLES){const b=button(p.name+' · 店铺资金 '+money(p.cost),()=>{if(game.buy(p.id))renderPanel();});b.disabled=s.wallet<p.cost||(s.purchases[p.id]||0)>=p.max||['circuit','scanner'].includes(p.id)&&s.upgrades[p.id];actions.push(b);}if(s.night===1)actions.push(button('提前离职，领取已有工资',()=>{if(game.retire())renderSettlement();},'subtle'));actions.push(button(s.night===2?'白天轮休 → 第三晚等候离站':'开始第二晚',()=>{if(game.nextNight()){modal=null;$('modal').hidden=true;play();}},'primary'));}else actions.push(button('查看本次剧情记录',()=>{modal='campaignRecords';panel('最后三班','STORY COMPLETE',s.history.map(v=>`<h3>第 ${v.night} 晚 · ${esc(v.title)}</h3><p>${esc(v.ending)} · 个人收入 ${money(v.net)}</p><p class="note">${esc(v.clue)}</p>`).join(''),[button('返回菜单',()=>{game.s.finished=true;modal=null;showMenu();},'primary')]);},'primary'));panel('第 '+s.night+' 晚 · '+last.title,'PERSONAL SAVINGS / STORE BUDGET',body,actions);}

function interact(){if(menu||modal||game.s.deathCinematic||game.s.recovery||world.controlTransition||sequenceActive(game.s))return;if(world.device){sceneInteraction.key('KeyE');return;}const s=game.s,t=world.targetAt(s,true);if(!t)return;if(t.blocked){notice('再靠近一点。');return;}if(t.id==='unhide'){game.leaveHide();return;}
 if(s.binocularActive){notice('先按 B 收起望远镜，再操作物品。');return;}if((s.carry||s.boardCarry||s.trapCarry)&&['monitor','terminal','actor','pump','register'].includes(t.id)){game.hands();return;}
 if(s.carry&&!['shelf','receiving','door','loadingSwitch'].includes(t.id)){notice('先按 Q 放下货箱。');return;}
 if(t.id==='actor'&&['story-worker','cal'].includes(t.key)&&game.s.phase!=='customers'){game.act(t.id,t.key);return;}
 if(['monitor','terminal','actor','pump','register','drawer','cashNote'].includes(t.id)){sceneInteraction.open(['drawer','cashNote'].includes(t.id)?'register':t.id,t.key);return;}
 if(t.id==='cashReset'){if(game.act('cashReset'))sceneInteraction.open('register');return;}
 if(t.id==='tender'){if(game.act('tender')&&game.s.transaction?.stage==='change')sceneInteraction.open('register');return;}
 if(t.id==='radio'&&s.campaign&&!isNewStory(s)&&s.night===3&&s.phase==='siege'){sceneInteraction.open('radio');return;}
 if(['manual','map'].includes(t.id)){if(t.id==='actor'&&s.actor.mode!=='wait'){notice('对方还在走近，等他停下再交谈。');return;}openPanel(t.id);return;}
 game.act(t.id,t.key);
}
const chapters={incident:'04 / 当班异常',callback:'04 / 假调班',investigate:'04 / 谁还在上班',preparation:'01 / 暂停营业',pickup:'02 / 核实接应',evacuation:'06 / 安全离站',briefing:'01 / 接班',opening:'02 / 开门营业',customers:'03 / 不速之客',outage:'04 / 照明中断',siege:'05 / 坚守',dawn:'06 / 天亮以前'};
const hudValues=new Map();function setHUD(id,key,value){const stamp=id+':'+key;if(hudValues.get(stamp)===value)return;hudValues.set(stamp,value);$(id)[key]=value;}
function hud(){const s=game.s,t=s.campaign?(campaignTask(s)||task(s)):task(s);if(s.campaign&&s.phase==='customers'){const pending=s.actors.filter(a=>a.mode==='wait'&&(person(s,a.id).rear||person(s,a.id).pump)).map(a=>person(s,a.id).rear?'后门有人等候':'三号泵呼叫');if(pending.length)t.detail+=' 另有：'+pending.join('、')+'。';}if(world.device==='register'){t.title='找零';t.detail='点击钱箱面额直接交给顾客；找齐自动结账；Backspace 撤回尚未完成的找零，Q 退出后可继续。';}setHUD('task-title','textContent',t.title);setHUD('task-detail','textContent',t.detail);setHUD('chapter','textContent',(s.campaign?'NIGHT '+s.night+' · ':'')+(chapters[s.phase]||'交班'));const minutes=storyClockMinutes(s);setHUD('clock','textContent',String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0'));setHUD('status','textContent',s.power?(s.campaign?'NIGHT '+s.night+' / 3 · 1996':'FIRST SHIFT · 1996'):'POWER FAILURE');const target=!s.paused&&!sequenceActive(s)&&!sceneInteraction.active&&!s.scannerActive&&!s.binocularActive?world.targetAt(s):null;reticle=target;world.hoverTarget=target;if(target){$('prompt').style.display='block';$('prompt').classList.toggle('blocked',!!target.blocked);setHUD('prompt','innerHTML',(target.blocked?'靠近 · ':'<kbd>E</kbd>　')+esc(target.name));}else $('prompt').style.display='none';
 const spokenCaption=characterVoice.caption;const funds=$('rent-progress');if(funds)funds.textContent='租房基金 '+money(s.rentFund||0)+' / '+money(s.rentTarget||30000)+'　·　店铺资金 '+money(s.wallet||0);$('subtitle').style.display=(spokenCaption||s.subtitleUntil>s.time&&s.subtitle)&&!sceneInteraction.actorId?'block':'none';setHUD('subtitle','textContent',spokenCaption||s.subtitle);
 const held=s.carry?s.crates[s.carry.id]:null;setHUD('inventory','innerHTML',[held?SHELVES[held.shelf].name+'货箱 · <kbd>Q</kbd> 放下':'',s.boardCarry?'木板 · <kbd>E</kbd> 按住钉牢 · <kbd>Q</kbd> 放回':'',s.torchOwned?`<kbd>F</kbd> 手电 ${s.torch?'开':'关'}`:'',s.campaign&&s.heldId?'证件 · '+person(s,s.heldId).name:'',s.binocularOwned?'<kbd>B</kbd> 望远镜'+(s.binocularActive?' · '+s.binocularZoom.toFixed(1)+'× · 滚轮变焦':''):'',s.doorKeyOwned?'门控钥匙 · 柜台下按钮':'',s.gunOwned?`<kbd>G</kbd> 应急手枪 ${s.gunDrawn?'已拔出':''}　${s.ammo}/${s.ammoCapacity||8}`:''].filter(Boolean).join('<br>'));
 const hp=$('hp-hud');hp.querySelector('span').textContent='HP '+Math.ceil(s.health)+' / 100';hp.querySelector('i').style.width=Math.max(0,s.health)+'%';hp.classList.toggle('critical',s.health<=36);const intro=$('tool-hint');intro.hidden=s.night!==1||s.time>180||(s.torchOwned&&s.gunOwned);intro.textContent=[!s.torchOwned?'柜台上：手电筒 · E 拿取':'',!s.gunOwned?'柜台下：打开安全抽屉，拿取八发手枪':''].filter(Boolean).join('　｜　');
 const changeHUD=$('change-hud'),transaction=s.transaction;changeHUD.hidden=world.device!=='register';if(!changeHUD.hidden&&transaction)changeHUD.textContent='应收 '+money(transaction.total)+'　实收 '+money(transaction.tender)+'　应找 '+money(transaction.tender-transaction.total)+'　已找 '+money(transaction.change)+'　还差 '+money(transaction.tender-transaction.total-transaction.change)+'　｜ 找齐自动完成 · Backspace 撤回未完成找零 · Q 退出';
 document.body.classList.toggle('binocular-active',!!s.binocularActive&&!s.paused);setHUD('binocular-zoom','textContent',(s.binocularZoom||1).toFixed(1)+'×');$('board-progress').hidden=!s.boardBuild;if(s.boardBuild)setHUD('board-progress','textContent','钉牢木板 '+Math.min(100,Math.floor(s.boardBuild.time/.95*100))+'% · 按住 E');document.body.classList.toggle('sheltered',s.hidden);$('damage').style.opacity=String((100-s.health)/360);if(performance.now()>toastUntil)$('toast').classList.remove('visible');
 playerShell.updateHUD({state:s,task:t,now:performance.now(),device:world.device});
 if(s.campaign&&s.phase==='settlement'&&!menu&&!modal)openPanel('settlement');
 if(s.finished&&!menu&&!modal)openPanel('records');
}
function move(dt){const s=game.s;if(s.paused||world.controlTransition||sequenceActive(s)||s.deathCinematic||s.recovery||s.hidden||s.finished||world.device||s.boardBuild){s.moving=false;return;}let x=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0);s.moving=!!(x||z);if(!s.moving)return;const len=Math.hypot(x,z);x/=len;z/=len;const carry=!!s.carry||s.boardCarry||s.trapCarry,run=keys.has('ShiftLeft')||keys.has('ShiftRight'),speed=(carry?(run?3.15:2.3):(run?4.05:2.9))*(s.scannerActive||s.binocularActive?.72:1),dx=(x*Math.cos(s.player.yaw)-z*Math.sin(s.player.yaw))*speed*dt,dz=(-x*Math.sin(s.player.yaw)-z*Math.cos(s.player.yaw))*speed*dt;
 const steps=Math.ceil(Math.hypot(dx,dz)/.08);for(let i=0;i<steps;i++){const nx=s.player.x+dx/steps,nz=s.player.z+dz/steps;if(world.canPlayerMove(nx,s.player.z,s))s.player.x=nx;if(world.canPlayerMove(s.player.x,nz,s))s.player.z=nz;}if(run)s.noise=.6;if(s.time-lastFoot>(run?.32:.49)){sound('foot',{surface:world.zone(s.player)});lastFoot=s.time;}
}
document.addEventListener('keydown',e=>{if(e.code==='F2'){e.preventDefault();return;}if(playerShell.transition){e.preventDefault();return;}if(!menu&&!modal&&['Tab','Space','Escape','KeyW','KeyA','KeyS','KeyD'].includes(e.code))e.preventDefault();if(opening.active){e.preventDefault();if(!e.repeat)opening.key(e.code);return;}if(e.code==='Escape'){if(!modal&&!menu&&sceneInteraction.active){sceneInteraction.close();return;}if(modal)closePanel();else if(menu){if(!playerShell.escape()&&game.s.time>0&&!game.s.finished)play();}else showMenu();return;}if(menu||game.s.deathCinematic||sequenceActive(game.s))return;if(e.code==='Tab'){if(modal==='notes')closePanel();else openPanel('notes');return;}if(e.code==='KeyH'){notice('员工手册贴在柜台后方公告板上，到板前按 E 阅读。');return;}if(e.code==='KeyM'){if(modal==='map')closePanel();else openPanel('map');return;}if(modal||e.repeat||game.s.paused||game.s.recovery)return;if(sceneInteraction.key(e.code)){e.preventDefault();return;}keys.add(e.code);if(e.code==='KeyE')interact();if(e.code==='KeyQ'){const t=world.targetAt(game.s);if(game.s.heldId){if(t?.id==='actor'&&t.key===game.s.heldId){game.focus(t.key);game.returnDocument();}else notice('面对证件本人，按 Q 归还证件。');}else{game.s.boardBuild=null;game.drop();}}if(e.code==='KeyB'){const s=game.s;if(!s.binocularOwned)notice('望远镜在柜台前端，先拿起。');else if(!s.carry&&!s.boardCarry&&!s.hidden&&!s.gunDrawn){s.binocularActive=!s.binocularActive;s.scannerActive=false;}}if(e.code==='KeyF'){if(game.s.torchOwned){if(game.s.hidden)notice('先按 E 离开储物柜，再打开手电。');else game.s.torch=!game.s.torch;}else notice('手电在柜台右端，先靠近按 E 拿起。');}if(e.code==='KeyG'){if(game.s.gunOwned&&!game.s.carry&&!game.s.boardCarry&&!game.s.trapCarry&&!game.s.hidden){game.s.gunDrawn=!game.s.gunDrawn;game.s.scannerActive=false;game.s.binocularActive=false;sceneInteraction.close();}else notice(!game.s.gunOwned?'应急手枪在柜台下抽屉，拿取后才能使用。':game.s.hidden?'先按 E 离开储物柜。':'先按 Q 放下手中的东西，再拔枪。');}});
document.addEventListener('keyup',e=>keys.delete(e.code));document.addEventListener('mousemove',e=>{if(document.pointerLockElement&&!opening.active&&!game.s.paused&&!game.s.deathCinematic&&!sequenceActive(game.s)&&!world.device){game.s.player.yaw-=e.movementX*sensitivity;game.s.player.pitch=Math.max(-1.25,Math.min(1.25,game.s.player.pitch-e.movementY*sensitivity));}});
document.addEventListener('pointerlockchange',()=>{if(opening.active){if(document.pointerLockElement){opening.hadPointerLock=true;}else if(opening.hadPointerLock&&!opening.paused){opening.pointerLostAt=performance.now();opening.setPaused(true);}return;}if(world.device==='register'&&!menu&&!modal){if(document.pointerLockElement)document.exitPointerLock?.();if(!game.s.paused)$('resume').hidden=true;return;}if(!document.pointerLockElement&&!menu&&!modal&&!seamlessControl&&!game.s.finished&&!sceneInteraction.active&&world.device!=='register'){game.s.paused=true;keys.clear();$('resume').hidden=false;}else if(document.pointerLockElement&&!menu&&!modal){seamlessControl=false;game.s.paused=false;$('resume').hidden=true;}});
world.renderer.domElement.addEventListener('mousedown',e=>{if(opening.active||menu||modal||game.s.deathCinematic||game.s.recovery||sequenceActive(game.s))return;if(world.device==='register'){if(e.button===0)sceneInteraction.clickMoney(e.clientX,e.clientY);return;}if(!document.pointerLockElement){lock();return;}if(e.button===0){if(game.s.gunDrawn){if(game.s.ammo)game.fire(world.shoot());else notice('没有子弹了。利用门、木板和视线脱身。');}else interact();}});document.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('scene-focus-opened',()=>{keys.clear();$('resume').hidden=true;});
window.addEventListener('cash-view-opened',()=>{keys.clear();$('resume').hidden=true;});
