world.renderer.domElement.addEventListener('mousemove',e=>{if(world.device==='register')world.cashHover=world.moneyBins.findIndex(g=>g.children[0].userData.target.key===world.cashAt(e.clientX,e.clientY)?.key);});
$('resume').querySelector('button').onclick=()=>{game.s.paused=false;$('resume').hidden=true;$('resume').querySelector('button').textContent='点击继续 / 锁定鼠标';lock();};$('music-choice').onchange=e=>music.select(e.target.value==='none'?null:e.target.value);$('music-volume').oninput=e=>music.volume=Number(e.target.value);$('dynamic-lighting').onchange=e=>{world.setDynamicLighting(e.target.checked);saveDynamicLighting(e.target.checked);};$('quality').onchange=e=>{quality=Number(e.target.value);world.resize(quality);};$('volume').oninput=e=>{volume=Number(e.target.value);soundscape.setVolume(volume);};$('sensitivity').oninput=e=>{sensitivity=Number(e.target.value);};window.addEventListener('pagehide',()=>persistSession(game,{openingActive:opening.active}));window.addEventListener('resize',()=>world.resize(quality));window.addEventListener('blur',()=>{keys.clear();if(opening.active){opening.setPaused(true);return;}if(!menu&&!modal){game.s.paused=true;$('resume').hidden=false;}});
world.renderer.domElement.addEventListener('wheel',e=>{if(game.s.binocularActive&&!game.s.paused&&!modal){e.preventDefault();game.s.binocularZoom=Math.max(1,Math.min(3,(game.s.binocularZoom||1)-e.deltaY*.002));}},{passive:false});
function frame(now){const rawDt=(now-last)/1000,dt=Math.min(.05,rawDt);last=now;if(opening.active){opening.advance(rawDt);if(opening.active){world.sync(game.s,dt);weather.update(game.s,dt);opening.apply(dt);soundscape.update({...game.s,paused:opening.paused,finished:false},world);music.update(game.s,{opening:true,voice:!!opening.voice.playingId,paused:opening.paused});world.render();}requestAnimationFrame(frame);return;}move(dt);game.tick(dt);game.buildBoard(dt,keys.has('KeyE'));sceneInteraction.tick();world.speakingId=characterVoice.current?.line.actorId;world.sync(game.s,dt);weather.update(game.s,dt);updateDialogueCamera(world,game.s,sceneInteraction,dt);updateStoryPresentation(world,game.s,dt);updateCinematicBlend(world,game.s,dt);updateDeathPresentation(world,game.s);if(!game.s.paused&&!game.s.deathCinematic&&!sequenceActive(game.s))game.observe(world.observeVisible(game.s));if(!game.s.paused&&!game.s.deathCinematic&&!sequenceActive(game.s)&&game.s.phone&&game.s.time-ambience>3.5){sound('ring');ambience=game.s.time;}hud();if(!game.s.deathCinematic)characterVoice.sync(game.s,{conversationId:sceneInteraction.actorId});soundscape.update(game.s,world);music.update(game.s,{voice:characterVoice.speaking,paused:!!game.s.deathCinematic||game.s.paused});if($('music-choice'))$('music-choice').value=music.style||'none';if(menu)playerShell.drawBackdrop(world);world.render();if(menu)playerShell.afterBackdrop(world);requestAnimationFrame(frame);}
const prefs=readPreferences();
for(const [id,lo,hi] of [['quality',360,900],['volume',0,1],['music-volume',0,.8],['sensitivity',.0006,.0035]]){const el=$(id),v=Number(prefs[id]);if(prefs[id]!=null&&Number.isFinite(v)&&v>=lo&&v<=hi&&(id!=='quality'||['360','480','540','720','900'].includes(String(v))))el.value=String(v);el.oninput?.({target:el});el.onchange?.({target:el});}
function savePlayerPreferences(){const p={};for(const id of ['quality','volume','music-volume','sensitivity'])p[id]=Number($(id).value);writePreferences(p);for(const out of document.querySelectorAll('output[for]')){const id=out.getAttribute('for'),value=Number($(id).value);out.textContent=id==='sensitivity'?Math.round((value-.0006)/.0029*100)+'%':Math.round(value*100)+'%';}}
for(const id of ['quality','volume','music-volume','sensitivity']){for(const type of ['input','change'])$(id).addEventListener(type,savePlayerPreferences);}savePlayerPreferences();
$('dynamic-lighting').checked=loadDynamicLighting();world.setDynamicLighting($('dynamic-lighting').checked);document.body.classList.add('menu');showMenu();world.sync(game.s,0);world.characterWarmup?.promise.then(()=>{if(menu){const page=playerShell.current;showMenu();playerShell.page(page);}}).catch(()=>{$('menu-actions').innerHTML='<p>场景准备失败，请刷新页面重试。</p>';});requestAnimationFrame(frame);
